const cfg = $('00 Einstellungen').first().json;
let modelle;
try { modelle = JSON.parse(cfg.modelle); } catch (e) { modelle = []; }
const opt = String(cfg.chatInput || '').match(/modelle:(\S+)/i);
if (opt) modelle = opt[1].split(',').map(s => s.trim()).filter(Boolean);
if (!modelle.length) {
  return [{ json: { fehler: 'Keine Modelle eingestellt. Im Knoten 00 Einstellungen die Liste "modelle" füllen.' } }];
}

const system = [
  'Du bist Autor eines Sachbuchs für Amazon KDP. Schreibe auf Deutsch, so dass es sich anhört wie von einem erfahrenen Menschen geschrieben: konkrete Beispiele, kurze und lange Sätze gemischt, direkte Ansprache, keine Floskeln.',
  'Regel: Schreibe nur Tatsachen, die du sicher weißt. Erfinde keine Gerichtsurteile, Aktenzeichen, Zahlen, Studien oder Zitate. Wenn du etwas nicht sicher weißt, lass es weg oder schreibe, dass es geprüft werden muss.'
].join('\n');
const user = [
  'Schreibe das Kapitel "Notwehr: Was ich darf und was nicht" für ein Buch "Selbstverteidigung für Frauen" (Altersstufe +18).',
  'Umfang: etwa 600 bis 800 Wörter.',
  'Inhalt: Notwehr nach § 32 StGB (gegenwärtiger rechtswidriger Angriff, Erforderlichkeit, Gebotenheit), Überschreitung der Notwehr nach § 33 StGB, ein kurzes Beispiel aus dem Alltag, ein Merkkasten mit drei Sätzen.',
  'Am Ende ein Haftungshinweis, dass dies keine Rechtsberatung ist. Nenne keine Urteile.'
].join('\n');

return modelle.map(m => ({ json: { modell: m, requestBody: {
  model: m, temperature: 0.6,
  messages: [ { role: 'system', content: system }, { role: 'user', content: user } ]
} } }));

const cfg = $('00 Einstellungen').first().json;
const auftraege = $('01 Aufträge bauen').all();
const antworten = $input.all();

const FLOSKELN = ['in der heutigen welt', 'zusammenfassend lässt sich sagen', 'tauchen wir ein', 'es ist wichtig zu beachten', 'in der heutigen zeit', 'zusammenfassend kann man sagen', 'letztendlich', 'spielt eine entscheidende rolle'];
const QUELLEN = /\b(BGH|BVerfG|BAG|OLG|LG|AG)\b|\bAz\.?\s|\b\d+\s*(StR|Ss|Ws|Js)\s*\d+|urteil vom|beschluss vom/i;

const ergebnisse = antworten.map((a, i) => {
  const modell = (auftraege[i] && auftraege[i].json.modell) || ('Modell ' + (i + 1));
  const j = a.json || {};
  const text = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content;
  if (!text) {
    const msg = (j.error && (j.error.message || JSON.stringify(j.error))) || j.message || JSON.stringify(j).slice(0, 200);
    return { modell, ok: false, fehler: String(msg) };
  }
  const t = String(text);
  const woerter = (t.match(/\S+/g) || []).length;
  const low = t.toLowerCase();
  const floskeln = FLOSKELN.filter(f => low.includes(f));
  const pruefung = {
    woerter,
    laenge_ok: woerter >= 500 && woerter <= 950,
    nennt_par32: /§\s*32/.test(t),
    nennt_par33: /§\s*33/.test(t),
    haftungshinweis: /keine rechtsberatung|ersetzt keine/i.test(t),
    verdaechtige_quellen: QUELLEN.test(t),
    floskeln,
    tokens: j.usage || null
  };
  return { modell, ok: true, pruefung, text: t };
});

const L = ['MODELLTEST Testkapitel "Notwehr" (automatische Vorprüfung, ersetzt dein Urteil nicht)', ''];
for (const e of ergebnisse) {
  if (!e.ok) { L.push('- ' + e.modell + ': KEINE ANTWORT (' + e.fehler + ')'); continue; }
  const p = e.pruefung;
  L.push('- ' + e.modell + ': ' + p.woerter + ' Wörter' + (p.laenge_ok ? '' : ' (außerhalb 500-950)')
    + ' | § 32: ' + (p.nennt_par32 ? 'ja' : 'NEIN') + ' | § 33: ' + (p.nennt_par33 ? 'ja' : 'NEIN')
    + ' | Haftungshinweis: ' + (p.haftungshinweis ? 'ja' : 'NEIN')
    + ' | verdächtige Quellen/Urteile: ' + (p.verdaechtige_quellen ? 'JA, prüfen' : 'nein')
    + ' | Floskeln: ' + (p.floskeln.length ? p.floskeln.join(', ') : 'keine'));
}
L.push('');
L.push('Die vollständigen Texte stehen in der Datei. Lies sie und bewerte nach docs/TESTKAPITEL.md: klingt es menschlich, stimmt es, ist es brauchbar?');

const d = new Date();
const stamp = d.getFullYear() + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0') + '-' + String(d.getHours()).padStart(2, '0') + String(d.getMinutes()).padStart(2, '0');
const name = 'modelltest__' + stamp + '.json';
const antwort = L.join('\n');
return [{
  json: { pfad: cfg.ausgabe_basis + '/' + name, antwort },
  binary: { data: { data: Buffer.from(JSON.stringify({ erstellt: d.toISOString(), ergebnisse }, null, 2), 'utf8').toString('base64'), mimeType: 'application/json', fileName: name, fileExtension: 'json' } }
}];
